import time

from robot.libraries.BuiltIn import BuiltIn
from taf.hw.pdu import pdu
from taf.rfrl.procedures.resources.python.logger import log_input_and_output, log_suppression
from taf.rfrl.procedures.resources.python.testline.TestLine import TestLine

from taf.rfrl.procedures.resources.python.power.exceptions import \
    UnexistingSerialNumber, MissingPduPort, NoMatchingPdu, PduActionFailed


class Power(object):
    """
    Responsible for power management of devices connected to PDU.

    It allows to perform certain PDU actions based on devices configurations and PDUs configurations
    loaded from testline config file (init).

    Currently supported devices:
      * gNB SMOD
      * gNB RMOD
      * eNB SMOD
      * eNB RMOD
      * attenuator
      * optical switch
    """

    _pdu_alias = 'power_manager'
    _post_action_wait_time = 5
    _power_off_time_while_resetting = 20
    _pdu_action_max_attempts = 20

    def __init__(self):
        """ Sets up PDU API. """
        self._pdu_api = pdu()
        self._testline = TestLine()

    @property
    def current_pdus_configs(self):
        """
        Returns PDUs configurations from tl variable.
        :returns: current used PDUs
        :rtype: list
        """
        testline_config = BuiltIn().get_variable_value('${tl}')
        return self._get_pdus_configs(testline_config)

    @property
    def current_devices_configs(self):
        """
        Returns devices configurations from tl variable.
        :returns: currently used devices
        :rtype: dict
        """
        testline_config = BuiltIn().get_variable_value('${tl}')
        return self._get_devices_configs(testline_config)

    @property
    def default_pdus_configs(self):
        """
        Returns PDUs configurations from default_tl variable.
        :returns: default PDUs
        :rtype: list
        """
        testline_config = BuiltIn().get_variable_value('${default_tl}')
        return self._get_pdus_configs(testline_config)

    @property
    def default_devices_configs(self):
        """
        Returns devices configurations from default_tl variable.
        :returns: default devices
        :rtype: dict
        """
        testline_config = BuiltIn().get_variable_value('${default_tl}')
        return self._get_devices_configs(testline_config)

    @log_input_and_output
    def turn_on_device(self, serial_number):
        """
        Turns power on for device with given serial number by powering on appropriate PDU port.

        :param serial_number: unique serial number of device which should be turned on; must exist in TL config file
        :type serial_number: str
        :raises UnexistingSerialNumber: when device with given serial number is not found in TL config file
        :raises MissingPduPort: when device doesn't have pdu_port specified in TL config file
        :raises NoMatchingPdu: when tl.pdus list from TL config file doesn't contain PDU to which device is connected
        :raises PduActionFailed: when attempted PDU action fails after multiple retires
        """
        pdu_port = self._get_pdu_port(serial_number)
        pdu_config = self._get_pdu_config(pdu_port, serial_number)
        self._setup_pdu(pdu_config)
        self._try_to_perform_action_on_pdu_and_return_output(pdu_action=self._pdu_api.power_on,
                                                             pdu_ip=pdu_config.addr,
                                                             port=pdu_port.port_no)

    @log_input_and_output
    def turn_off_device(self, serial_number):
        """
        Turns power off for device with given serial number by powering off appropriate PDU port.

        :param serial_number: unique serial number of device which should be turned off; must exist in TL config file
        :type serial_number: str
        :raises UnexistingSerialNumber: when device with given serial number is not found in TL config file
        :raises MissingPduPort: when device doesn't have pdu_port specified in TL config file
        :raises NoMatchingPdu: when tl.pdus list from TL config file doesn't contain PDU to which device is connected
        :raises PduActionFailed: when attempted PDU action fails after multiple retires
        """
        pdu_port = self._get_pdu_port(serial_number)
        pdu_config = self._get_pdu_config(pdu_port, serial_number)
        self._setup_pdu(pdu_config)
        self._try_to_perform_action_on_pdu_and_return_output(pdu_action=self._pdu_api.power_off,
                                                             pdu_ip=pdu_config.addr,
                                                             port=pdu_port.port_no)

    @log_input_and_output
    def get_pdu_status_for_device(self, serial_number):
        """
        Returns PDU port status for device with given serial number.

        :param serial_number: unique serial number of device which swill be checked; must exist in TL config file
        :type serial_number: str
        :return: possible PDU port states: 'on' or 'off' or 'reset' (if the port is in currently resetting).
        :rtype: str
        :raises UnexistingSerialNumber: when device with given serial number is not found in TL config file
        :raises MissingPduPort: when device doesn't have pdu_port specified in TL config file
        :raises NoMatchingPdu: when tl.pdus list from TL config file doesn't contain PDU to which device is connected
        :raises PduActionFailed: when attempted PDU action fails after multiple retires
        """
        pdu_port = self._get_pdu_port(serial_number)
        pdu_config = self._get_pdu_config(pdu_port, serial_number)
        self._setup_pdu(pdu_config)
        return self._try_to_perform_action_on_pdu_and_return_output(pdu_action=self._pdu_api.get_port_status,
                                                                    pdu_ip=pdu_config.addr,
                                                                    port=pdu_port.port_no)

    @log_input_and_output
    def reset_device(self, serial_number):
        """
        Resets power for device with given serial number by resetting appropriate PDU port.

        :param serial_number: unique serial number of device which should be reset; must exist in TL config file
        :type serial_number: str
        :raises UnexistingSerialNumber: when device with given serial number is not found in TL config file
        :raises MissingPduPort: when device doesn't have pdu_port specified in TL config file
        :raises NoMatchingPdu: when tl.pdus list from TL config file doesn't contain PDU to which device is connected
        :raises PduActionFailed: when attempted PDU action fails after multiple retires
        """
        pdu_port = self._get_pdu_port(serial_number)
        pdu_config = self._get_pdu_config(pdu_port, serial_number)
        self._setup_pdu(pdu_config)
        self._try_to_perform_action_on_pdu_and_return_output(pdu_action=self._pdu_api.reset_ports,
                                                             pdu_ip=pdu_config.addr,
                                                             ports=[pdu_port.port_no],
                                                             time_interval=self._power_off_time_while_resetting)

    @log_input_and_output
    def turn_on_all_gnb_smods(self):
        """
        Turns power on for all gNB SMODs connected to PDU by powering on appropriate PDU ports.

        :raises NoMatchingPdu: when tl.pdus list from TL config file doesn't contain PDU to which gNB SMOD is connected
        :raises PduActionFailed: when attempted PDU action fails after multiple retires
        """
        devices_config = self.current_devices_configs['gnb_smods']
        if devices_config:
            self._turn_on_all('gnb_smods')

