    @staticmethod
    @log_input_and_output
    def _get_pdus_configs(testline_config):
        return testline_config.pdus

    @log_input_and_output
    def _get_devices_configs(self, testline_config):
        return {'gnb_smods': self._get_gnb_smods_configs(testline_config),
                'gnb_rmods': self._get_gnb_rmods_configs(testline_config),
                'enb_smods': self._get_enb_smods_configs(testline_config),
                'enb_rmods': self._get_enb_rmods_configs(testline_config),
                'attenuators': self._get_attenuators_configs(testline_config),
                'optical_switches': self._get_optical_switches_configs(testline_config),
                }

    def _get_gnb_smods_configs(self, testline_config):
        if testline_config.gnbs is not None:
            return self._testline.get_smods_configs(custom_init=testline_config)
        return []

    def _get_gnb_rmods_configs(self, testline_config):
        if testline_config.gnbs is not None:
            return self._testline.get_radios_configs(custom_init=testline_config)
        return []

    def _get_enb_smods_configs(self, testline_config):
        if testline_config.enbs is not None:
            return self._testline.get_smods_configs(bts_type='ENB', custom_init=testline_config)
        return []

    def _get_enb_rmods_configs(self, testline_config):
        if testline_config.enbs is not None:
            return self._testline.get_radios_configs(bts_type='ENB', custom_init=testline_config)
        return []

    @staticmethod
    def _get_attenuators_configs(testline_config):
        return testline_config.attenuators if testline_config.attenuators != [None] else []

    @staticmethod
    def _get_optical_switches_configs(testline_config):
        return testline_config.optical_switches if testline_config.optical_switches else []

    @log_input_and_output
    def _get_pdu_port(self, device_serial_number):
        try:
            return self._get_pdu_port_from_config(config=self.current_devices_configs,
                                                  device_serial_number=device_serial_number)
        except UnexistingSerialNumber:
            return self._get_pdu_port_from_config(config=self.default_devices_configs,
                                                  device_serial_number=device_serial_number)

    def _get_pdu_port_from_config(self, config, device_serial_number):
        for devices_configs in config.values():
            for device_config in devices_configs:
                if hasattr(device_config, "serial_number"):
                    if device_config.serial_number == device_serial_number:
                        self._check_if_device_has_pdu_port(device_config)
                        return device_config.pdu_port

        raise UnexistingSerialNumber("Device with serial number: {} couldn't be found in "
                                     "testline configuration file".format(device_serial_number))

    @staticmethod
    def _check_if_device_has_pdu_port(device_config):
        if device_config.pdu_port is None:
            raise MissingPduPort("Device with serial number: {} has no pdu_port attribute specified in "
                                 "testline configuration file".format(device_config.serial_number))

    @log_input_and_output
    def _get_pdu_config(self, device_pdu_port, device_serial_number):
        try:
            return self._get_pdu_from_config(config=self.current_pdus_configs,
                                             device_pdu_port=device_pdu_port,
                                             device_serial_number=device_serial_number)
        except NoMatchingPdu:
            return self._get_pdu_from_config(config=self.default_pdus_configs,
                                             device_pdu_port=device_pdu_port,
                                             device_serial_number=device_serial_number)

    def _get_pdu_from_config(self, config, device_pdu_port, device_serial_number):
        for pdu_config in config:
            for pdu_port in pdu_config.pdu_ports.values():
                if pdu_port is device_pdu_port:
                    return pdu_config

        raise NoMatchingPdu("Device with serial number: {} has no matching PDU for "
                            "port number: {} in testline configuration file. "
                            "Check tl.pdus list for missing PDU object.".format(device_serial_number,
                                                                                device_pdu_port.port_no))

    @log_input_and_output
    def _setup_pdu(self, pdu_config):
        pdu_setup_data = {'model': pdu_config.vendor,
                          'host': pdu_config.addr,
                          'version': pdu_config.version,
                          'alias': self._pdu_alias}

        if hasattr(pdu_config, 'snmp_user') and pdu_config.snmp_user is not None:
            pdu_setup_data['snmp_user'] = pdu_config.snmp_user

        self._pdu_api.setup_pdu(**pdu_setup_data)

    def _turn_on_all(self, devices_type):
        pdu_ports = self._get_pdu_ports_grouped_by_pdu(devices_type)

        for pdu_config, ports in pdu_ports.items():
            self._turn_on_pdu_ports(pdu_config, ports)

    def _turn_off_all(self, devices_type):
        pdu_ports = self._get_pdu_ports_grouped_by_pdu(devices_type)

        for pdu_config, ports in pdu_ports.items():
            self._turn_off_pdu_ports(pdu_config, ports)

    def _reset_all(self, devices_type):
        pdu_ports = self._get_pdu_ports_grouped_by_pdu(devices_type)

        for pdu_config, ports in pdu_ports.items():
            self._reset_pdu_ports(pdu_config, ports)

    def _get_pdu_ports_grouped_by_pdu(self, devices_type):
        grouped_pdu_ports = {}

        for device_config in self.current_devices_configs[devices_type]:
            pdu_port = device_config.pdu_port

            if pdu_port is not None:
                serial_number = device_config.serial_number
                pdu_config = self._get_pdu_config(pdu_port, serial_number)

                if pdu_config not in grouped_pdu_ports:
                    grouped_pdu_ports[pdu_config] = [pdu_port]
                elif pdu_port not in grouped_pdu_ports[pdu_config]:
                    grouped_pdu_ports[pdu_config].append(pdu_port)

        return grouped_pdu_ports

    @log_input_and_output
    def _turn_on_pdu_ports(self, pdu_config, pdu_ports):
        self._setup_pdu(pdu_config)
        pdu_ports = [port.port_no for port in pdu_ports]
        for pdu_port in pdu_ports:
            self._try_to_perform_action_on_pdu_and_return_output(pdu_action=self._pdu_api.power_on,
                                                                 pdu_ip=pdu_config.addr,
                                                                 port=pdu_port)

    @log_input_and_output
    def _turn_off_pdu_ports(self, pdu_config, pdu_ports):
        self._setup_pdu(pdu_config)
        pdu_ports = [port.port_no for port in pdu_ports]
        for pdu_port in pdu_ports:
            self._try_to_perform_action_on_pdu_and_return_output(pdu_action=self._pdu_api.power_off,
                                                                 pdu_ip=pdu_config.addr,
                                                                 port=pdu_port)

    @log_input_and_output
    def _reset_pdu_ports(self, pdu_config, pdu_ports):
        self._setup_pdu(pdu_config)
        pdu_ports = [port.port_no for port in pdu_ports]
        self._try_to_perform_action_on_pdu_and_return_output(pdu_action=self._pdu_api.reset_ports,
                                                             pdu_ip=pdu_config.addr,
                                                             ports=pdu_ports,
                                                             time_interval=self._power_off_time_while_resetting)

    @log_input_and_output
    def _try_to_perform_action_on_pdu_and_return_output(self, pdu_action, pdu_ip, **kwargs):
        attempts_count = 1
        pdu_api_error = None
        pdu_output = None

        while attempts_count <= self._pdu_action_max_attempts:
            try:
                pdu_output = pdu_action(pdu_device=self._pdu_alias, **kwargs)
            except Exception as error:
                pdu_api_error = error
                attempts_count += 1
                log_suppression(f'Retrying PDU action due to following error: {pdu_api_error.__class__.__name__}: {pdu_api_error}')
            else:
                break
            finally:
                time.sleep(self._post_action_wait_time)

        if attempts_count > self._pdu_action_max_attempts:
            pdu_port_number = kwargs.get('port', kwargs.get('ports', [None])[0])
            raise PduActionFailed("Performing {} action on PDU with IP address: {} and port number: {} failed after "
                                  "{} retries due to following error: {}: {}".format(pdu_action.__name__,
                                                                                     pdu_ip,
                                                                                     pdu_port_number,
                                                                                     self._pdu_action_max_attempts,
                                                                                     pdu_api_error.__class__.__name__,
                                                                                     pdu_api_error))
        return pdu_output
